package com.mamtrex.hospital.emergency;
import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="emergency_visits") public class EmergencyVisit extends BaseEntity { private String patientId; private String arrivalAt; private String triageLevel; private String chiefComplaint; private String status; protected EmergencyVisit(){} public EmergencyVisit(String patientId, String arrivalAt, String triageLevel, String chiefComplaint, String status){this.patientId=patientId; this.arrivalAt=arrivalAt; this.triageLevel=triageLevel; this.chiefComplaint=chiefComplaint; this.status=status;} public String getPatientId(){return patientId;} public String getArrivalAt(){return arrivalAt;} public String getTriageLevel(){return triageLevel;} public String getChiefComplaint(){return chiefComplaint;} public String getStatus(){return status;} }
